import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// Dev: `npm run dev` on :5173 proxies /api to the FastAPI server on :8000.
// Build: output goes to ./dist, which the FastAPI app serves at "/".
// Static read-only build for Vercel: `npm run build:static` -> apps/lab/dist/dashboard, reading the
// precomputed JSON in public/data (generated by tools/build_deploy.py from the real API).
export default defineConfig(({ mode }) => ({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: { "/api": "http://127.0.0.1:8000" },
  },
  define: mode === "static" ? { "import.meta.env.VITE_STATIC": JSON.stringify("1") } : {},
  build: { outDir: "dist", emptyOutDir: true },
}));
